#!/usr/bin/env bash
set -euo pipefail
IMAGE=${1:?Usage: $0 image.raw}
OUT=${2:-case-output}
mkdir -p "$OUT"
{
  echo "UTC=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo "IMAGE=$IMAGE"
  echo "COMMAND=mmls $IMAGE"
  mmls "$IMAGE"
} | tee "$OUT/mmls.txt"

OFFSET=${OFFSET:-0}
{
  echo "COMMAND=fls -r -o $OFFSET $IMAGE"
  fls -r -o "$OFFSET" "$IMAGE"
} | tee "$OUT/fls.txt"

finding = {
  "observation": "Three independent artifacts occur in a consistent temporal sequence.",
  "interpretation": "The sequence supports a common activity window involving the target item.",
  "limitation": "The artifacts do not independently identify the human actor or intent."
}
print(finding)
